{
  "model": "deepseek-v4-flash",
  "messages": [
    {
      "role": "system",
      "content": "Ты — ассистент по официальным курсам валют ЦБ РФ. Курсы и пересчёты бери только из инструментов и никогда не называй курс по памяти. Даты передавай в формате ГГГГ-ММ-ДД; сегодня 2026-09-22. В ответе назови дату курса, которую вернул инструмент, и числа из его результата. Если инструмент вернул ошибку — исправь аргументы или объясни пользователю, что не так. Если вопрос не про курсы и пересчёт валют — отвечай без инструментов. Отвечай по-русски и кратко."
    },
    {
      "role": "user",
      "content": "Переведи на английский: курс валюты"
    }
  ],
  "stream": false,
  "temperature": 0,
  "thinking": {
    "type": "disabled"
  },
  "tools": [
    {
      "type": "function",
      "function": {
        "name": "convert_currency",
        "description": "Конвертирует сумму по официальным курсам ЦБ РФ к рублю на дату ГГГГ-ММ-ДД; RUB разрешён, всегда берите курсы из этого инструмента, а не из памяти.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "amount": {
              "description": "Сумма для конвертации, должна быть больше нуля.",
              "type": "number"
            },
            "date": {
              "description": "Дата курса в формате ГГГГ-ММ-ДД; если не указана, берётся последний курс.",
              "type": "string"
            },
            "from": {
              "description": "Исходная валюта ISO 4217 или RUB.",
              "type": "string"
            },
            "to": {
              "description": "Целевая валюта ISO 4217 или RUB.",
              "type": "string"
            }
          },
          "required": [
            "amount",
            "from",
            "to"
          ],
          "type": "object"
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "get_currency_rates",
        "description": "Возвращает официальные курсы ЦБ РФ к рублю на дату ГГГГ-ММ-ДД; всегда берите курсы из этого инструмента, а не из памяти.",
        "parameters": {
          "additionalProperties": false,
          "properties": {
            "codes": {
              "description": "Коды валют ISO 4217; если не указаны или пусты, возвращаются все валюты.",
              "items": {
                "type": "string"
              },
              "type": [
                "null",
                "array"
              ]
            },
            "date": {
              "description": "Дата курса в формате ГГГГ-ММ-ДД; если не указана, берётся последний курс.",
              "type": "string"
            }
          },
          "type": "object"
        }
      }
    }
  ]
}

